// BlitzLLVM help: search, theme switch, copy buttons and the menu on small screens. The pages work without it.
(function () {
	"use strict";
	var doc = document.documentElement;
	var root = doc.getAttribute("data-root") || "";
	doc.classList.add("js");

	function store(key, value) {
		try {
			if (value === undefined) return localStorage.getItem(key);
			if (value === null) localStorage.removeItem(key); else localStorage.setItem(key, value);
		} catch (e) { /* file:// in some browsers, private windows */ }
		return null;
	}

	function show(el) { if (el) el.hidden = false; }

	// --- Theme: follows the system until picked; auto -> light -> dark -> auto. ---------------------------------
	var themeButton = document.querySelector(".theme");
	var themeNames = { "": "follows the system", light: "light", dark: "dark" };
	function setTheme(t) {
		if (t) doc.dataset.theme = t; else delete doc.dataset.theme;
		store("blitzllvm-help-theme", t || null);
		if (themeButton) themeButton.title = "Theme: " + themeNames[t || ""];
	}
	if (themeButton) {
		show(themeButton);
		setTheme(doc.dataset.theme || "");
		themeButton.addEventListener("click", function () {
			var t = doc.dataset.theme || "";
			setTheme(t === "" ? "light" : t === "light" ? "dark" : "");
		});
	}

	// --- Menu on small screens. --------------------------------------------------------------------------------------
	var menu = document.querySelector(".menu-toggle");
	if (menu) {
		show(menu);
		menu.addEventListener("click", function () {
			var open = document.body.classList.toggle("nav-open");
			menu.setAttribute("aria-expanded", open ? "true" : "false");
		});
		document.addEventListener("click", function (e) {
			if (document.body.classList.contains("nav-open") && !e.target.closest(".side") && !e.target.closest(".menu-toggle")) {
				document.body.classList.remove("nav-open");
				menu.setAttribute("aria-expanded", "false");
			}
		});
	}
	// Keep the current entry of the sidebar in view.
	var current = document.querySelector('.side [aria-current="page"]');
	if (current && current.scrollIntoView) current.scrollIntoView({ block: "center" });

	// --- Copy buttons. -----------------------------------------------------------------------------------------------
	document.querySelectorAll(".code .copy").forEach(function (button) {
		show(button);
		button.addEventListener("click", function () {
			var text = button.closest(".code").querySelector("pre").innerText;
			var done = function () {
				button.textContent = "Copied";
				button.classList.add("done");
				setTimeout(function () { button.textContent = "Copy"; button.classList.remove("done"); }, 1500);
			};
			if (navigator.clipboard && window.isSecureContext) {
				navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });
			} else {
				fallbackCopy(text);
				done();
			}
		});
	});
	function fallbackCopy(text) {
		var area = document.createElement("textarea");
		area.value = text;
		area.style.position = "fixed";
		area.style.opacity = "0";
		document.body.appendChild(area);
		area.select();
		try { document.execCommand("copy"); } catch (e) { /* nothing more to try */ }
		area.remove();
	}

	// --- Sounds: a click plays the sound in the page instead of opening it; another click stops it. ---------------
	var playing = null;
	document.querySelectorAll("a.play").forEach(function (link) {
		link.addEventListener("click", function (e) {
			e.preventDefault();
			var again = playing && playing.link === link;
			if (playing) { playing.audio.pause(); playing.link.classList.remove("playing"); playing = null; }
			if (again) return;
			var audio = new Audio(link.href);
			playing = { audio: audio, link: link };
			link.classList.add("playing");
			audio.addEventListener("ended", function () { link.classList.remove("playing"); if (playing && playing.link === link) playing = null; });
			audio.play().catch(function () { link.classList.remove("playing"); location.href = link.href; });
		});
	});

	// --- Search. ----------------------------------------------------------------------------------------------------
	// The index (assets/search.js) is a script, not JSON, because pages opened from the disk may not fetch() files.
	var input = document.getElementById("search");
	var list = document.getElementById("search-results");
	if (!input || !list) return;
	var loading = false, selected = -1, results = [];
	var KINDS = ["", "Category", "Guide"];

	function load(then) {
		if (window.HELP_INDEX) return then();
		if (loading) return;
		loading = true;
		var s = document.createElement("script");
		s.src = root + "assets/search.js";
		s.onload = function () { then(); };
		document.head.appendChild(s);
	}

	function escapeHtml(s) {
		return s.replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; });
	}

	function words(name) { return name.match(/[A-Z]+(?![a-z])|[A-Z][a-z0-9]*|[a-z0-9]+/g) || []; }

	// The letters of t in order inside name ("entcol" finds EntityColor); returns how many letters it skipped, or -1.
	function subsequence(name, t) {
		var at = 0, skipped = 0;
		for (var i = 0; i < t.length; i++) {
			var j = name.indexOf(t[i], at);
			if (j < 0) return -1;
			skipped += j - at;
			at = j + 1;
		}
		return t.length > 1 ? skipped * 4 : -1;
	}

	// Lower is better. Names first: exact, prefix, a word of the name (CamelCase), anywhere; then the summary.
	function score(entry, terms) {
		var name = entry[0].toLowerCase(), rest = (entry[3] + " " + entry[4]).toLowerCase(), total = 0;
		for (var i = 0; i < terms.length; i++) {
			var t = terms[i], s;
			if (name === t) s = 0;
			else if (name.indexOf(t) === 0) s = 10 + name.length - t.length;
			else if (words(entry[0]).some(function (w) { return w.toLowerCase().indexOf(t) === 0; })) s = 40 + name.length;
			else if (name.indexOf(t) >= 0) s = 60 + name.length;
			else if ((s = subsequence(name, t)) >= 0) s += 100 + name.length;
			else if (rest.indexOf(t) >= 0) s = 300;
			else return -1;
			total += s;
		}
		return total + entry[2] * 5;
	}

	// Highlights the letters of the first term: the substring if there is one, otherwise the letters in order.
	function mark(name, terms) {
		var low = name.toLowerCase(), t = terms[0] || "", i = low.indexOf(t), hit = [];
		if (!t) return escapeHtml(name);
		if (i >= 0) for (var k = i; k < i + t.length; k++) hit[k] = true;
		else for (var n = 0, at = 0; n < t.length; n++) { var j = low.indexOf(t[n], at); if (j < 0) break; hit[j] = true; at = j + 1; }
		var out = "";
		for (var c = 0; c < name.length; c++) out += hit[c] ? "<mark>" + escapeHtml(name[c]) + "</mark>" : escapeHtml(name[c]);
		return out.replace(/<\/mark><mark>/g, "");
	}

	function run() {
		var q = input.value.trim().toLowerCase();
		if (!q) return close();
		var terms = q.split(/\s+/);
		var scored = [];
		window.HELP_INDEX.forEach(function (e) {
			var s = score(e, terms);
			if (s >= 0) scored.push([s, e]);
		});
		scored.sort(function (a, b) { return a[0] - b[0] || a[1][0].localeCompare(b[1][0]); });
		results = scored.slice(0, 40).map(function (x) { return x[1]; });
		selected = results.length ? 0 : -1;
		list.innerHTML = results.length ? results.map(function (e, i) {
			return '<li role="option" id="sr-' + i + '"' + (i === selected ? ' aria-selected="true"' : "") + '><a href="' + root + e[1] + '">' +
				'<span class="r-where">' + escapeHtml(KINDS[e[2]] ? KINDS[e[2]] + " · " + e[3] : e[3]) + "</span>" +
				'<span class="r-name">' + mark(e[0], terms) + "</span>" +
				(e[4] ? '<span class="r-sum">' + escapeHtml(e[4]) + "</span>" : "") + "</a></li>";
		}).join("") : '<li class="r-none">Nothing found for “' + escapeHtml(input.value.trim()) + '”.</li>';
		list.hidden = false;
		input.setAttribute("aria-expanded", "true");
		input.setAttribute("aria-activedescendant", selected >= 0 ? "sr-0" : "");
	}

	function close() {
		list.hidden = true;
		input.setAttribute("aria-expanded", "false");
		selected = -1;
	}

	function select(i) {
		if (!results.length) return;
		selected = (i + results.length) % results.length;
		list.querySelectorAll("li").forEach(function (li, n) {
			if (n === selected) { li.setAttribute("aria-selected", "true"); li.scrollIntoView({ block: "nearest" }); }
			else li.removeAttribute("aria-selected");
		});
		input.setAttribute("aria-activedescendant", "sr-" + selected);
	}

	input.addEventListener("focus", function () { load(function () { if (input.value) run(); }); });
	input.addEventListener("input", function () { load(run); });
	input.addEventListener("keydown", function (e) {
		if (e.key === "ArrowDown") { e.preventDefault(); select(selected + 1); }
		else if (e.key === "ArrowUp") { e.preventDefault(); select(selected - 1); }
		else if (e.key === "Enter") {
			e.preventDefault();
			if (selected >= 0 && results[selected]) location.href = root + results[selected][1];
		} else if (e.key === "Escape") { close(); input.blur(); }
	});
	document.addEventListener("click", function (e) { if (!e.target.closest(".search")) close(); });
	document.addEventListener("keydown", function (e) {
		var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
		if (!typing && (e.key === "/" || ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k"))) {
			e.preventDefault();
			input.focus();
			input.select();
		}
	});
	document.querySelectorAll(".search-focus").forEach(function (b) {
		show(b);
		b.addEventListener("click", function () { input.focus(); });
	});
	// ?q=Name opens the search with that text, so editors can link to it.
	var q = /[?&]q=([^&]*)/.exec(location.search);
	if (q) {
		input.value = decodeURIComponent(q[1].replace(/\+/g, " "));
		load(run);
	}
})();
